'use strict';
/* ============================================================
   NAM '68 — top-down wave shooter. (c) iron triangle 1968
   ============================================================ */
const CV = document.getElementById('cv'), CX = CV.getContext('2d');
const WW = 1500, WH = 1150;              // world size
const VW = 1280, VH = 720;               // viewport
const TAU = Math.PI * 2;
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const rnd = (a, b) => a + Math.random() * (b - a);
const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
const ang = (ax, ay, bx, by) => Math.atan2(by - ay, bx - ax);
const lerp = (a, b, t) => a + (b - a) * t;

/* ---------------- weapon pricing (requisition store) ---------------- */
const CAT_LABEL = { AR: 'RIFLE', BR: 'BATTLE RIFLE', SM: 'SMG', SG: 'SHOTGUN', SN: 'SNIPER', MG: 'LMG', PI: 'PISTOL', SP: 'SPECIAL' };
const CAT_PRICE = { PI: 34, SM: 52, SG: 66, AR: 92, BR: 104, SN: 138, MG: 185, SP: 205 };
for (const w of WEAPONS) {
  let autoBonus = (w.md === 'auto' ? 12 : 0) + (w.pc > 1 ? 8 : 0);
  w.price = Math.round(CAT_PRICE[w.c] + w.d * 1.15 + w.m * 0.5 + autoBonus);
}

/* ---------------- persistent profile ---------------- */
const SAVE_KEY = 'nam68_v2';
const DEF = () => ({
  name: '', skin: 0, head: 0, paint: 0, cloth: 0, boots: 0, armor: 0,
  primary: 'M3 Grease Gun', sidearm: 'M1911A1 .45',
  ownedW: ['M3 Grease Gun', 'M1911A1 .45'],
  ownedArm: [0], ownedCloth: [0], ownedBoots: [0],
  req: ECON.startReq, bestRound: 0, bestScore: 0, totalKills: 0, bosses: 0,
});
let S = DEF();
try { const raw = localStorage.getItem(SAVE_KEY); if (raw) S = Object.assign(DEF(), JSON.parse(raw)); } catch (e) { }
const save = () => { try { localStorage.setItem(SAVE_KEY, JSON.stringify(S)); } catch (e) { } };
const wByName = n => WEAPONS.find(w => w.n === n);
const armorById = i => ARMORS[i] || ARMORS[0];

/* ---------------- audio (tiny synth) ---------------- */
let AC = null, NOISE = null;
function audio() {
  if (!AC) {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    NOISE = AC.createBuffer(1, AC.sampleRate * 0.5, AC.sampleRate);
    const d = NOISE.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  }
  if (AC.state === 'suspended') AC.resume();
  return AC;
}
function boom(vol = .5, dur = .18, f0 = 900, f1 = 140, type = 'lowpass') {
  const ac = audio(); if (!ac) return;
  const src = ac.createBufferSource(); src.buffer = NOISE;
  const flt = ac.createBiquadFilter(); flt.type = type;
  flt.frequency.setValueAtTime(f0, ac.currentTime);
  flt.frequency.exponentialRampToValueAtTime(f1, ac.currentTime + dur);
  const g = ac.createGain();
  g.gain.setValueAtTime(vol, ac.currentTime);
  g.gain.exponentialRampToValueAtTime(.001, ac.currentTime + dur);
  src.connect(flt); flt.connect(g); g.connect(ac.destination);
  src.start(); src.stop(ac.currentTime + dur);
}
function tone(freq, dur, vol = .2, type = 'square', slide = 0) {
  const ac = audio(); if (!ac) return;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type; o.frequency.setValueAtTime(freq, ac.currentTime);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq - slide), ac.currentTime + dur);
  g.gain.setValueAtTime(vol, ac.currentTime);
  g.gain.exponentialRampToValueAtTime(.001, ac.currentTime + dur);
  o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime + dur);
}
function sShot(w) {
  const c = w ? w.c : 'AR';
  if (c === 'PI') boom(.22, .1, 1600, 500);
  else if (c === 'SN') { boom(.4, .3, 1500, 100); tone(120, .12, .12, 'sawtooth', 60); }
  else if (c === 'MG') boom(.3, .12, 900, 200);
  else if (c === 'SG') boom(.42, .22, 1100, 90);
  else if (c === 'SP') { tone(220, .2, .2, 'sawtooth', 140); boom(.3, .25, 500, 80); }
  else boom(.26, .13, 1400, 220);
}
const sHit = () => boom(.16, .07, 700, 300);
const sHurt = () => { boom(.3, .2, 500, 100); tone(90, .18, .2, 'sawtooth', 50); };
const sExpl = () => { boom(.6, .5, 300, 40); tone(70, .35, .3, 'sawtooth', 40); };
const sDry = () => tone(700, .04, .08, 'square', 300);
const sReload = () => { tone(500, .05, .1, 'square'); setTimeout(() => tone(700, .05, .1, 'square'), 120); };
const sCash = () => { tone(880, .07, .12, 'square'); setTimeout(() => tone(1320, .09, .12, 'square'), 70); };
const sHeal = () => tone(520, .15, .1, 'sine', 200);
const sBoss = () => { tone(60, .8, .35, 'sawtooth', 20); boom(.4, .7, 400, 60); };
const sGren = () => tone(240, .12, .15, 'sine', 120);

/* ---------------- drawing helpers ---------------- */
function drawSoldier(c, x, y, a, k) {
  // k: {body, alt, skin, head, paint, prot, scale}
  const s = k.scale || 1;
  c.save(); c.translate(x, y);
  c.fillStyle = 'rgba(0,0,0,.3)'; c.beginPath(); c.ellipse(2, 4, 13 * s, 9 * s, 0, 0, TAU); c.fill();
  c.rotate(a + Math.PI / 2);
  // shoulders/torso
  c.fillStyle = k.body; c.beginPath(); c.ellipse(0, 0, 9.5 * s, 12 * s, 0, 0, TAU); c.fill();
  c.fillStyle = k.alt; c.beginPath(); c.ellipse(0, 3 * s, 7 * s, 6 * s, 0, 0, TAU); c.fill();
  // vest
  if (k.prot > 0) {
    c.fillStyle = 'rgba(30,30,24,' + Math.min(.75, k.prot * 1.4) + ')';
    c.beginPath(); c.ellipse(0, 1 * s, 9 * s, 9 * s, 0, 0, TAU); c.fill();
    c.strokeStyle = 'rgba(200,190,150,.25)'; c.stroke();
  }
  // arms + rifle
  c.strokeStyle = k.body; c.lineWidth = 4 * s; c.lineCap = 'round';
  c.beginPath(); c.moveTo(7 * s, 2 * s); c.lineTo(13 * s, -6 * s); c.stroke();
  c.beginPath(); c.moveTo(-7 * s, 2 * s); c.lineTo(3 * s, -8 * s); c.stroke();
  c.strokeStyle = '#2b2317'; c.lineWidth = 3.4 * s;
  c.beginPath(); c.moveTo(4 * s, -3 * s); c.lineTo(19 * s, -13 * s); c.stroke();
  // head
  c.fillStyle = k.skin; c.beginPath(); c.arc(0, 1.5 * s, 5.6 * s, 0, TAU); c.fill();
  if (k.paint === 1) { c.fillStyle = 'rgba(20,40,15,.75)'; c.fillRect(-5 * s, -1 * s, 4 * s, 2.4 * s); c.fillRect(1.5 * s, -1.5 * s, 4 * s, 2.4 * s); }
  if (k.paint === 2) { c.fillStyle = 'rgba(15,32,12,.8)'; c.fillRect(-6 * s, 0, 12 * s, 3 * s); c.fillStyle = 'rgba(90,80,40,.5)'; c.fillRect(-6 * s, -3 * s, 12 * s, 3 * s); }
  // headwear
  if (k.head === 0) { c.fillStyle = '#4a4a33'; c.beginPath(); c.arc(0, 1.5 * s, 6.1 * s, 0, TAU); c.fill(); c.strokeStyle = 'rgba(0,0,0,.35)'; c.lineWidth = 1.2; c.stroke(); }
  else if (k.head === 1) { c.fillStyle = '#a3402e'; c.beginPath(); c.arc(0, .2 * s, 5.8 * s, Math.PI, TAU); c.fill(); c.fillRect(-5.8 * s, .2 * s, 11.6 * s, 2 * s); }
  else if (k.head === 2) { c.fillStyle = '#8a7b4e'; c.beginPath(); c.arc(0, 1.5 * s, 6.2 * s, 0, TAU); c.fill(); c.fillStyle = 'rgba(138,123,78,.8)'; c.beginPath(); c.arc(0, 1.5 * s, 9 * s, 0, TAU); c.stroke(); c.strokeStyle = 'rgba(138,123,78,.9)'; c.lineWidth = 1.4; c.beginPath(); c.arc(0, 1.5 * s, 9 * s, 0, TAU); c.stroke(); }
  else { c.fillStyle = 'rgba(30,22,12,.9)'; c.beginPath(); c.arc(0, -.5 * s, 5 * s, Math.PI, TAU); c.fill(); }
  c.restore();
}

/* ---------------- prerendered jungle ground ---------------- */
const ground = document.createElement('canvas'); ground.width = WW; ground.height = WH;
function paintGround() {
  const g = ground.getContext('2d');
  for (let y = 0; y < WH; y += 24) for (let x = 0; x < WW; x += 24) {
    const v = rnd(0, 1);
    g.fillStyle = v < .45 ? '#2c3a24' : v < .75 ? '#314027' : '#263420';
    g.fillRect(x, y, 24, 24);
  }
  for (let i = 0; i < 60; i++) {
    g.strokeStyle = rnd(0, 1) < .5 ? 'rgba(80,105,55,.25)' : 'rgba(40,58,30,.4)';
    g.lineWidth = rnd(1, 3); const x = rnd(0, WW), y = rnd(0, WH);
    g.beginPath(); g.moveTo(x, y); g.quadraticCurveTo(x + rnd(-30, 30), y - rnd(10, 40), x + rnd(-60, 60), y - rnd(30, 80)); g.stroke();
  }
  for (let i = 0; i < 26; i++) { // dirt patches
    g.fillStyle = 'rgba(110,92,60,' + rnd(.08, .2) + ')';
    g.beginPath(); g.ellipse(rnd(0, WW), rnd(0, WH), rnd(30, 110), rnd(20, 70), rnd(0, TAU), 0, TAU); g.fill();
  }
}

/* ---------------- game state ---------------- */
const G = {
  scene: 'title', run: null, cam: { x: 0, y: 0 }, shake: 0,
  mx: 0, my: 0, md: false, keys: {}, showF: 0,
};
function newRun() {
  const arm = armorById(S.armor), cloth = CLOTHES[S.cloth], boots = BOOTS[S.boots];
  const p = {
    x: WW / 2, y: WH / 2, r: 12, ang: 0, spdBase: 190, hp: 100, hpMax: 100,
    prot: arm.prot, spdMul: (arm.spd * boots.spd),
    stamina: 100, sprint: false,
    w1: mkGun(wByName(S.primary)), w2: mkGun(wByName(S.sidearm)), wi: 1,
    grenades: 4, iFrames: 0, hurtT: 0,
  };
  return {
    round: 1, kills: 0, score: 0, cashRun: 0, p,
    enemies: [], bullets: [], pickups: [], parts: [], lobs: [],
    toSpawn: 0, spawnT: 0, alive: 0, boss: null, bossSeq: 0, state: 'fight',
    obstacles: [], decals: 0,
  };
}
function mkGun(w) {
  if (!w) return null;
  return { w, mag: w.m, reserve: w.m * 4, cool: 0, reload: 0 };
}
function armorClothAll() {
  const cloth = CLOTHES[S.cloth] || CLOTHES[0];
  return { body: cloth.body, alt: cloth.alt, skin: SKINS[S.skin], head: S.head, paint: S.paint, prot: armorById(S.armor).prot };
}

/* ---------------- rounds & spawning ---------------- */
function roundEnemies(r) {
  const cap = 5 + Math.min(21, Math.floor(r * 1.9));
  let hpMul = 1 + (r - 1) * .085, spdMul = Math.min(1.55, 1 + (r - 1) * .018);
  if (R.bossSeq > 0) { hpMul *= 1 + R.bossSeq * .35; }
  const types = ['grunt', 'grunt', 'rusher'];
  if (r >= 3) types.push('sapper');
  if (r >= 5) types.push('sniper');
  if (r >= 7) types.push('grenadier');
  if (r >= 9) types.push('heavy');
  return { cap, hpMul, spdMul, types };
}
let R = null;
function beginRound() {
  if (R.run.round % 10 === 0) { spawnBoss(); }
  else {
    const re = roundEnemies(R.run.round);
    R.run.toSpawn = re.cap;
    R.roundCfg = re;
  }
  // top up mags + partial reserve
  const p = R.run.p;
  for (const g of [p.w1, p.w2]) { g.mag = g.w.m; g.reserve = Math.min(g.w.m * 4, g.reserve + g.w.m * 2); }
  p.grenades = Math.min(6, p.grenades + 2);
  p.hp = Math.min(p.hpMax, p.hp + 40);
}
function spawnAt(kind, cfg) {
  const edge = Math.floor(rnd(0, 4)); let x, y;
  if (edge === 0) { x = rnd(40, WW - 40); y = 30; }
  else if (edge === 1) { x = rnd(40, WW - 40); y = WH - 30; }
  else if (edge === 2) { x = 30; y = rnd(40, WH - 40); }
  else { x = WW - 30; y = rnd(40, WH - 40); }
  const t = ENEMY_TYPES[kind];
  const e = {
    kind, x, y, hp: t.hp * cfg.hpMul, hpMax: t.hp * cfg.hpMul, spd: t.spd * cfg.spdMul,
    r: t.r, cool: rnd(0, 1), ang: 0, t, strafe: rnd(-1, 1), meleeT: 0,
  };
  R.run.enemies.push(e); R.run.alive++;
}
function spawnBoss() {
  const b0 = BOSSES[R.run.round / 10 - 1 >= 0 ? (R.run.round / 10 - 1) % BOSSES.length : 0];
  const cyc = Math.floor((R.run.round / 10 - 1) / BOSSES.length);
  const hpMul = (1 + (R.run.round - 1) * .085) * (1 + cyc * .45);
  const b = {
    kind: 'boss', boss: b0, x: WW / 2, y: 60, hp: b0.hp * hpMul, hpMax: b0.hp * hpMul,
    spd: b0.spd, r: b0.r, cool: 2, ang: Math.PI / 2, t: { dmg: b0.dmg, rpm: 130, range: 600, spread: .06 }, strafe: rnd(-1, 1), summonT: 4,
  };
  R.run.boss = b; R.run.enemies.push(b);
  sBoss();
  R.banner = { t0: 60 * 3, txt: b0.name.toUpperCase() };
}
function obstacleGen() {
  const obs = [];
  for (let i = 0; i < 9; i++) {
    const x = rnd(120, WW - 120), y = rnd(120, WH - 120), r = rnd(40, 64);
    obs.push({ x, y, r, type: 'bags', hp: Infinity });
  }
  for (let i = 0; i < 12; i++) {
    const x = rnd(120, WW - 120), y = rnd(120, WH - 120), r = rnd(14, 18);
    obs.push({ x, y, r, type: 'trunk', hp: Infinity });
  }
  [[80, 80], [WW - 80, 80], [80, WH - 80], [WW - 80, WH - 80], [WW / 2, 70], [WW / 2, WH - 70]].forEach(([x, y]) => obs.push({ x, y, r: 34, type: 'sandbag' }));
  return obs;
}

/* ---------------- input ---------------- */
addEventListener('keydown', e => {
  const k = e.key.toLowerCase(); G.keys[k] = true;
  if (e.key === 'Escape') {
    if (G.scene === 'game') pause(true);
    else if (G.scene === 'paused') pause(false);
  }
  if (G.scene !== 'game') return;
  if (k === 'r') startReload();
  if (k === '1' || k === '2') switchWeapon(+k);
  if (k === 'g') throwGrenade();
  if (k === ' ') e.preventDefault();
});
addEventListener('keyup', e => G.keys[e.key.toLowerCase()] = false);
CV.addEventListener('mousemove', e => {
  const r = CV.getBoundingClientRect();
  G.mx = (e.clientX - r.left) * (CV.width / r.width); G.my = (e.clientY - r.top) * (CV.height / r.height);
});
CV.addEventListener('mousedown', e => { audio(); if (G.scene === 'game') { G.md = true; if (G.run.p.wi === 2) fireTick(true); } });
addEventListener('mouseup', () => G.md = false);
CV.addEventListener('contextmenu', e => e.preventDefault());

function pause(on) {
  if (!R) return;
  G.scene = on ? 'paused' : 'game';
  screen('scr-pause', on);
}
function startReload() {
  const p = R.run.p;
  const g = p.wi === 1 ? p.w1 : p.w2;
  if (g.reload > 0 || g.mag === g.w.m || g.reserve <= 0) return;
  g.reload = g.w.rl; sReload();
}
function switchWeapon(i) {
  const p = R.run.p; if (p.wi === i) return; p.wi = i; tone(300, .05, .08, 'square');
}
function throwGrenade() {
  const p = R.run.p; if (p.grenades <= 0) { sDry(); return; }
  p.grenades--; sGren();
  const a = p.ang;
  R.run.lobs.push({ x: p.x + Math.cos(a) * 16, y: p.y + Math.sin(a) * 16, vx: Math.cos(a) * 260, vy: Math.sin(a) * 260, t: .9, kind: 'frag' });
}

/* ---------------- shooting ---------------- */
function fireTick(clickOnly) {
  const p = R.run.p; if (p.iFrames > 20) { /* still shoot */ }
  const g = p.wi === 1 ? p.w1 : p.w2;
  const w = g.w;
  if (g.reload > 0) return;
  if (g.cool > 0) return;
  if (g.mag <= 0) { if (clickOnly) { sDry(); startReload(); } return; }
  const needClick = w.md !== 'auto';
  if (needClick && !clickOnly) return;
  g.cool = 60 / w.r; g.mag--;
  p.ang = Math.atan2(G.my + G.cam.y - p.y, G.mx + G.cam.x - p.x);
  sShot(w);
  G.shake = Math.min(10, G.shake + (w.c === 'SN' ? 5 : w.c === 'SG' ? 4 : 1.6));
  const n = w.pc || 1;
  for (let i = 0; i < n; i++) {
    const sp = w.sp * (n > 1 ? 1 : 1) + (n > 1 ? rnd(-w.sp * .25, w.sp * .25) : 0);
    const a = p.ang + rnd(-sp, sp);
    R.run.bullets.push({ x: p.x + Math.cos(p.ang) * 20, y: p.y + Math.sin(p.ang) * 20, vx: Math.cos(a) * 900, vy: Math.sin(a) * 900, dmg: w.d, from: 'p', r: w.c === 'SP' ? 4 : 2, range: w.rng, c: w.c });
  }
  for (let i = 0; i < 3; i++) R.parts.push(muzzle(p.x + Math.cos(p.ang) * 24, p.y + Math.sin(p.ang) * 24, p.ang));
}
function muzzle(x, y, a) { return { x, y, vx: Math.cos(a) * rnd(60, 200), vy: Math.sin(a) * rnd(60, 200), life: rnd(.04, .1), t: 0, kind: 'flash' }; }
function enemyFire(e, w, dmg) {
  const p = R.run.p;
  const a = ang(e.x, e.y, p.x, p.y) + rnd(-w.spread, w.spread);
  R.run.bullets.push({ x: e.x + Math.cos(a) * (e.r + 6), y: e.y + Math.sin(a) * (e.r + 6), vx: Math.cos(a) * 620, vy: Math.sin(a) * 620, dmg, from: 'e', r: 2.4, range: w.range, c: 'E' });
  boom(.12, .1, 1100, 250);
}

/* ---------------- damage ---------------- */
function hurtPlayer(d) {
  const p = R.run.p;
  if (p.iFrames > 0) return;
  const real = d * (1 - p.prot);
  p.hp -= real; p.iFrames = .25; p.hurtT = .4; G.shake = Math.min(14, G.shake + 4); sHurt();
  for (let i = 0; i < 5; i++) R.parts.push(blood(p.x, p.y, .4));
  if (p.hp <= 0) { p.hp = 0; die(); }
}
function hurtEnemy(e, d) {
  e.hp -= d; sHit();
  for (let i = 0; i < 4; i++) R.parts.push(blood(e.x, e.y, .35));
  if (e.hp <= 0) killEnemy(e);
}
function blood(x, y, s) { return { x, y, vx: rnd(-90, 90), vy: rnd(-90, 90), life: rnd(.2, .5), t: 0, kind: 'blood', s }; }
function killEnemy(e) {
  const p = R.run.p;
  R.run.kills++; S.totalKills++;
  const val = e.kind === 'boss' ? e.boss.score : e.t.score;
  R.run.score += val;
  const cash = Math.round(val * ECON.killRatio);
  addCash(cash, e.x, e.y);
  if (e.t && e.t.explode) explode(e.x, e.y, e.t.explode, 60, 'e');
  if (e.kind === 'boss') {
    explodeRange(e.x, e.y, 160, e.x < p.x ? 0 : 0); sExpl(); G.shake = 16;
    S.bosses++;
    for (let i = 0; i < 5; i++) R.run.pickups.push({ x: e.x + rnd(-40, 40), y: e.y + rnd(-40, 40), kind: i < 2 ? 'hp' : 'cash', v: 60, t: 0 });
  } else if (Math.random() < .22) {
    const kind = Math.random() < .45 ? 'hp' : Math.random() < .7 ? 'ammo' : 'cash';
    R.run.pickups.push({ x: e.x, y: e.y, kind, v: kind === 'cash' ? Math.round(rnd(25, 60)) : 0, t: 0 });
  }
  e.dead = true; R.run.alive--;
}
function explode(x, y, radius, dmg, side) {
  sExpl(); G.shake = 10;
  for (let i = 0; i < 22; i++) R.parts.push({ x, y, vx: rnd(-260, 260), vy: rnd(-260, 260), life: rnd(.2, .6), t: 0, kind: 'fire' });
  const p = R.run.p;
  if (side === 'e'()) { }
  R.run.enemies.forEach(en => { if (!en.dead && dist(en.x, en.y, x, y) < radius + en.r) { const d = dmg * (1 - dist(en.x, en.y, x, y) / (radius + en.r)); en.hp -= d * 1; if (en.hp <= 0) killEnemy(en); } });
  if (side !== 'e' && dist(p.x, p.y, x, y) < radius) hurtPlayer(dmg * .8);
}
function explodeRange() { }

function addCash(c, x, y) {
  S.req += c; R.run.cashRun += c;
  if (x !== undefined) floaty(x, y, '+$' + c);
  sCash(); save();
}
function floaty(x, y, txt) { R.run.parts.push({ x, y, vy: -40, vx: rnd(-10, 10), life: 1, t: 0, kind: 'txt', txt }); }

function die() {
  G.scene = 'over';
  explode(R.run.p.x, R.run.p.y, 120, 0, 'self'); sExpl();
  setTimeout(() => {
    saveBest();
    document.getElementById('overStats').innerHTML =
      `Spc. ${esc(S.name || 'Unknown')} — reached <b>round ${R.run.round}</b><br>
       ${R.run.kills} kills this run · score ${R.run.score} · requisition earned this run $${R.run.cashRun}`;
    screen('scr-over', true);
  }, 600);
}
function saveBest() {
  S.bestRound = Math.max(S.bestRound, R.run.round);
  S.bestScore = Math.max(S.bestScore, R.run.score);
  S.req += Math.round(R.run.round * 20); S.bestRound = S.bestRound; save();
}
const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

/* ---------------- update ---------------- */
let last = performance.now();
function tick(now) {
  const dt = Math.min(.05, (now - last) / 1000); last = now;
  if (G.scene === 'game' && R) update(dt);
  render(dt);
  requestAnimationFrame(tick);
}
function update(dt) {
  const ru = R.run, p = ru.p;
  // aim & move
  p.ang = Math.atan2(G.my + G.cam.y - p.y, G.mx + G.cam.x - p.x);
  let mx = (G.keys.d || G.keys.arrowright ? 1 : 0) - (G.keys.a || G.keys.arrowleft ? 1 : 0);
  let my = (G.keys.s || G.keys.arrowdown ? 1 : 0) - (G.keys.w || G.keys.arrowup ? 1 : 0);
  const mv = Math.hypot(mx, my) || 1;
  const wantSprint = G.keys.shift && p.stamina > 2;
  p.stamina = clamp(p.stamina + (wantSprint ? -32 : 20) * dt, 0, 100);
  const spd = p.spdBase * p.spdMul * (wantSprint ? 1.45 : 1) * (1 - .2) / 1;
  p.x = clamp(p.x + mx / mv * spd * dt, 20, WW - 20); p.y = clamp(p.y + my / mv * spd * dt, 20, WH - 20);
  for (const o of ru.obstacles) {
    const d = dist(p.x, p.y, o.x, o.y), min = o.r + p.r;
    if (d < min) { const nx = (p.x - o.x) / (d || 1), ny = (p.y - o.y) / (d || 1); p.x = o.x + nx * min; p.y = o.y + ny * min; }
  }
  p.iFrames = Math.max(0, p.iFrames - dt);
  p.hurtT = Math.max(0, p.hurtT - dt);

  // fire
  const g = p.wi === 1 ? p.w1 : p.w2;
  ['w1', 'w2'].forEach(k => { const gg = p[k]; gg.cool = Math.max(0, gg.cool - dt); if (gg.reload > 0) { gg.reload -= dt; if (gg.reload <= 0) { const need = gg.w.m - gg.mag, use = Math.min(need, gg.reserve); gg.mag += use; gg.reserve -= use; gg.reload = 0; } } });
  if (G.md) fireTick(false);

  // spawning
  if (!ru.boss && ru.toSpawn > 0) {
    ru.spawnT -= dt;
    if (ru.spawnT <= 0 && ru.enemies.length < 26) {
      ru.spawnT = Math.max(.35, 1.4 - ru.round * .05);
      const types = R.roundCfg.types;
      spawnAt(types[Math.floor(rnd(0, types.length))], R.roundCfg);
      ru.toSpawn--;
    }
  }
  if (!ru.boss && ru.toSpawn === 0 && ru.enemies.length === 0 && ru.state === 'fight') roundClear();

  // enemies
  for (const e of ru.enemies) {
    if (e.dead) continue;
    const a = ang(e.x, e.y, p.x, p.y); e.ang = a;
    const d = dist(e.x, e.y, p.x, p.y);
    let ww = e.t && e.t.weapon ? ENEMY_TYPES[e.kind].weapon : null;
    const range = e.kind === 'boss' ? e.t.range : (e.t.range || 0);
    const stopAt = range > 0 ? range * .85 : (e.kind === 'rusher' ? 20 : e.kind === 'sapper' ? 24 : 30);
    if (e.kind === 'rusher' || e.kind === 'sapper') {
      const sp = e.spd;
      e.x += Math.cos(a) * sp * dt + Math.cos(a + Math.PI / 2) * Math.sin(performance.now() / (e.kind === 'sapper' ? 300 : 500)) * 40 * dt;
      e.y += Math.sin(a) * sp * dt;
      if (e.kind === 'sapper' && d < e.r + p.r + 6) { explode(e.x, e.y, 70, e.t.dmg, 'e'); killEnemy(e); continue; }
      if (e.kind === 'rusher' && d < e.r + p.r + 4) { e.meleeT -= dt; if (e.meleeT <= 0) { hurtPlayer(e.t.dmg); e.meleeT = .8; } }
    } else {
      const sp = e.spd * (d < stopAt ? 0 : 1) + Math.sin(performance.now() / 600 + e.strafe) * 8;
      e.x += Math.cos(a) * sp * dt + Math.cos(a + Math.PI / 2) * e.strafe * (d < stopAt ? 22 : 6) * dt;
      e.y += Math.sin(a) * sp * dt + Math.sin(a + Math.PI / 2) * e.strafe * (d < stopAt ? 22 : 6) * dt;
      e.cool -= dt;
      if (d < range && e.cool <= 0) {
        e.cool = e.kind === 'boss' ? rnd(1.2, 2.2) : 60 / e.t.rpm + rnd(0, .4);
        if (e.kind === 'boss') {
          if (e.boss.gun) { for (let i = 0; i < e.boss.bursts; i++) setTimeout(() => { if (!e.dead && G.scene === 'game') enemyFire(e, e.t, e.t.dmg); }, i * 90); }
          e.summonT -= 1.7;
        } else if (e.kind === 'sniper') { enemyFire(e, e.t, e.t.dmg); tone(150, .1, .1, 'sawtooth'); }
        else if (e.kind === 'grenadier') {
          sGren();
          ru.lobs.push({ x: e.x, y: e.y, vx: Math.cos(a) * 300, vy: Math.sin(a) * 300, t: d / 300 * 1.05, dmg: e.t.dmg, kind: 'enemy' });
        } else enemyFire(e, e.t, e.t.dmg);
      }
    }
    // boss summons
    if (e.kind === 'boss') {
      e.summonT -= dt;
      if (e.summonT <= 0 && ru.enemies.length < 22) {
        e.summonT = e.boss.gun ? 7 : 3.4;
        for (let i = 0; i < 3; i++) { const cfg = roundEnemies(ru.round); spawnAt(e.boss.gun ? 'rusher' : 'sapper', cfg); }
        floaty(e.x, e.y - 20, 'calls in backup!');
      }
    }
    for (const o of ru.obstacles) {
      const dd = dist(e.x, e.y, o.x, o.y), mn = o.r + e.r;
      if (dd < mn) { const nx = (e.x - o.x) / (dd || 1), ny = (e.y - o.y) / (dd || 1); e.x = o.x + nx * mn; e.y = o.y + ny * mn; }
    }
  }

  // bullets
  for (const b of ru.bullets) {
    b.x += b.vx * dt; b.y += b.vy * dt; b.range -= Math.hypot(b.vx, b.vy) * dt;
    if (b.range <= 0 || b.x < 8 || b.y < 8 || b.x > WW - 8 || b.y > WH - 8) { b.dead = true; continue; }
    for (const o of ru.obstacles) if (dist(b.x, b.y, o.x, o.y) < o.r) { b.dead = true; break; }
    if (b.dead) continue;
    if (b.from === 'p') {
      for (const e of ru.enemies) { if (!e.dead && dist(b.x, b.y, e.x, e.y) < e.r + b.r) { hurtEnemy(e, b.dmg); b.dead = true; break; } }
    } else if (dist(b.x, b.y, p.x, p.y) < p.r + b.r) { hurtPlayer(b.dmg); b.dead = true; }
  }
  // lobs
  for (const L of ru.lobs) {
    L.x += L.vx * dt; L.y += L.vy * dt; L.t -= dt;
    if (L.t <= 0) {
      L.dead = true;
      if (L.kind === 'frag') explode(L.x, L.y, 96, 95, 'f');
      else explode(L.x, L.y, 80, L.dmg, 'e');
    }
  }
  // pickups
  for (const k of ru.pickups) {
    k.t += dt;
    if (k.t > 18) { k.dead = true; continue; }
    if (dist(k.x, k.y, p.x, p.y) < p.r + 12) {
      k.dead = true;
      if (k.kind === 'hp') { p.hp = Math.min(p.hpMax, p.hp + Math.max(25, k.v || 30)); sHeal(); floaty(k.x, k.y, 'medic!'); }
      else if (k.kind === 'ammo') {
        const gg = [p.w1, p.w2]; gg.forEach(q => q.reserve = Math.min(q.w.m * 4, q.reserve + q.w.m * 2)); floaty(k.x, k.y, 'ammo resupplied');
        tone(400, .1, .1, 'square');
      } else { addCash(k.v, k.x, k.y); }
    }
  }
  // particles
  for (const q of ru.parts) {
    q.t += dt; q.x += (q.vx || 0) * dt; q.y += (q.vy || 0) * dt;
    if (q.t > (q.life || .4)) q.dead = true;
  }
  ru.bullets = ru.bullets.filter(b => !b.dead);
  ru.lobs = ru.lobs.filter(l => !l.dead);
  ru.pickups = ru.pickups.filter(k => !k.dead);
  ru.parts = ru.parts.filter(q => !q.dead);
  ru.enemies = ru.enemies.filter(e => !e.dead);

  // camera
  G.cam.x = clamp(lerp(G.cam.x, clamp(p.x - VW / 2, 0, WW - VW), .12), 0, WW - VW);
  G.cam.y = clamp(lerp(G.cam.y, clamp(p.y - VH / 2, 0, WH - VH), .12), 0, WH - VH);
  G.shake = Math.max(0, G.shake - dt * 30);
  if (R.banner) { R.banner.t0 -= 60 * dt; if (R.banner.t0 <= 0) R.banner = null; }
}

function roundClear() {
  G.scene = 'inter';
  const bonus = ECON.clearBase + ECON.clearPerRound * R.run.round;
  S.req += bonus; R.run.cashRun += bonus;
  const kills = R.run.kills; const bossRound = R.run.round % 10 === 0;
  if (bossRound) { /* boss cash already added */ }
  save();
  document.getElementById('interTitle').textContent = bossRound ? 'BOSS DOWN — SECTOR CLEARED' : 'ROUND CLEARED';
  document.getElementById('irRound').textContent = R.run.round;
  document.getElementById('irKills').textContent = kills;
  document.getElementById('irCash').textContent = '$' + bonus;
  document.getElementById('irTotal').textContent = '$' + S.req;
  document.getElementById('irNote').textContent = bossRound
    ? 'Command extracted the target. Rest, rearm, req. bonus ' + (ECON.clearBase + ECON.clearPerRound * R.run.round) + ' credited.'
    : 'Req. bonus $' + bonus + ' credited. Next round will hit harder.';
  R.run.round++;           // next round prepared
  R.run.kills = 0;
  screen('scr-inter', true);
}
function deploy() {
  R = { run: newRun() };
  R.run.obstacles = obstacleGen();
  paintGround();   // fresh jungle
  R.roundCfg = roundEnemies(R.run.round);
  beginRound();
  G.cam.x = clamp(R.run.p.x - VW / 2, 0, WW - VW); G.cam.y = clamp(R.run.p.y - VH / 2, 0, WH - VH);
  G.scene = 'game';
  film(false);
}
function nextRound() {
  if (!R) { deploy(); return; }
  R.roundCfg = roundEnemies(R.run.round);
  beginRound();
  G.scene = 'game';
  film(false);
}

/* ---------------- render ---------------- */
function render(dt) {
  CX.save();
  CX.fillStyle = '#0d0c08'; CX.fillRect(0, 0, CV.width, CV.height);
  const inGame = ['game', 'paused', 'over', 'inter'].includes(G.scene);
  if (inGame && R) {
    const shx = G.shake > 0 ? rnd(-G.shake, G.shake) : 0, shy = G.shake > 0 ? rnd(-G.shake, G.shake) : 0;
    CX.translate(-G.cam.x + shx, -G.cam.y + shy);
    CX.drawImage(ground, 0, 0);
    drawObstacles();
    // pickups
    for (const k of R.run.pickups) drawPickup(k);
    // lob sprites
    for (const L of R.run.lobs) {
      CX.fillStyle = '#39392b'; CX.beginPath(); CX.arc(L.x, L.y, 4, 0, TAU); CX.fill();
      CX.fillStyle = 'rgba(120,120,100,.7)'; CX.beginPath(); CX.arc(L.x, L.y, 2, 0, TAU); CX.fill();
    }
    // corpse decorations (blood pools via particles)
    for (const q of R.run.parts) {
      if (q.kind === 'blood') { CX.fillStyle = 'rgba(120,20,15,' + clamp(1 - q.t / q.life, 0, .9) + ')'; CX.beginPath(); CX.arc(q.x, q.y, q.s * 26 * (q.t / q.life + .2), 0, TAU); CX.fill(); }
    }
    // enemies
    for (const e of R.run.enemies) {
      if (e.dead) continue;
      CX.save();
      if (e.kind === 'boss') {
        drawBoss(e);
      } else {
        const t = e.t;
        drawSoldier(CX, e.x, e.y, e.ang, { body: t.col, alt: '#1e241a', skin: '#c98d5f', head: 0, paint: e.kind === 'sapper' ? 2 : 1, prot: e.kind === 'heavy' ? .3 : 0, scale: e.r / 12 });
        // enemy hp bar
        if (e.hp < e.hpMax) { CX.fillStyle = '#000'; CX.fillRect(e.x - 14, e.y - 20, 28, 3); CX.fillStyle = '#b0473b'; CX.fillRect(e.x - 14, e.y - 20, 28 * clamp(e.hp / e.hpMax, 0, 1), 3); }
      }
      CX.restore();
    }
    // player
    const p = R.run.p;
    const arm = armorById(S.armor), cloth = CLOTHES[S.cloth] || CLOTHES[0];
    drawSoldier(CX, p.x, p.y, p.ang, Object.assign(armorClothAll(), { scale: 1 }));
    if (p.iFrames > 0) { CX.fillStyle = 'rgba(255,80,60,' + p.iFrames * .4 + ')'; CX.beginPath(); CX.arc(p.x, p.y, 18, 0, TAU); CX.fill(); }
    // sprint dust
    if (G.keys.shift) { CX.fillStyle = 'rgba(150,130,90,.16)'; CX.beginPath(); CX.arc(p.x - Math.cos(p.ang) * 10 + rnd(-4, 4), p.y - Math.sin(p.ang) * 10 + rnd(-4, 4), 3, 0, TAU); CX.fill(); }
    // bullets
    for (const b of R.run.bullets) {
      CX.strokeStyle = b.from === 'p' ? '#ffe9a8' : '#ff8b6b';
      CX.lineWidth = b.r + (b.c === 'SN' ? 1 : 0);
      const tx = b.x - b.vx * .016, ty = b.y - b.vy * .016;
      CX.beginPath(); CX.moveTo(tx, ty); CX.lineTo(b.x, b.y); CX.stroke();
    }
    // fire / flash particles
    for (const q of R.run.parts) {
      const a = 1 - q.t / q.life;
      if (a <= 0) continue;
      if (q.kind === 'flash') { CX.fillStyle = 'rgba(255,210,110,' + a * .8 + ')'; CX.fillRect(q.x - 1, q.y - 1, 3, 3); }
      else if (q.kind === 'fire') { CX.fillStyle = 'rgba(255,' + Math.floor(120 + 100 * a) + ',40,' + a + ')'; CX.beginPath(); CX.arc(q.x, q.y, 4 + 10 * (1 - a), 0, TAU); CX.fill(); }
      else if (q.kind === 'txt') { CX.fillStyle = 'rgba(127,176,105,' + a + ')'; CX.font = 'bold 14px Georgia'; CX.textAlign = 'center'; CX.fillText(q.txt, q.x, q.y - (1 - a) * 22); }
    }
    // tree canopy overlay (shade circle above entities)
    for (const o of R.run.obstacles) {
      if (o.type !== 'trunk') continue;
      CX.fillStyle = 'rgba(24,36,18,.66)';
      CX.beginPath(); CX.arc(o.x, o.y - 2, 34, 0, TAU); CX.fill();
      CX.fillStyle = 'rgba(34,50,24,.6)';
      CX.beginPath(); CX.arc(o.x - 12, o.y + 8, 22, 0, TAU); CX.arc(o.x + 14, o.y + 2, 18, 0, TAU); CX.fill();
    }
    // world bounds hint
    CX.strokeStyle = 'rgba(200,168,75,.15)'; CX.lineWidth = 2; CX.strokeRect(4, 4, WW - 8, WH - 8);
    drawHUD();
    if (R.banner) {
      const a = clamp(R.banner.t0 / 90, 0, 1);
      CX.fillStyle = 'rgba(176,71,59,' + a + ')'; CX.font = 'bold 30px Georgia'; CX.textAlign = 'center';
      CX.fillText(R.banner.txt, G.cam.x + VW / 2, G.cam.y + 110);
    }
    // hurt vignette
    if (R.run.p.hurtT > 0) {
      CX.fillStyle = 'rgba(176,71,59,' + R.run.p.hurtT * .5 + ')';
      CX.fillRect(G.cam.x, G.cam.y, VW, VH);
    }
  } else {
    // ambient menu backdrop: faint map
    CX.globalAlpha = .5;
    if (ground.getContext) CX.drawImage(ground, -40, -30);
    CX.globalAlpha = 1;
  }
  CX.restore();
}
function drawObstacles() {
  for (const o of R.run.obstacles) {
    if (o.type === 'trunk') {
      CX.fillStyle = '#3a2b18'; CX.beginPath(); CX.arc(o.x, o.y, o.r, 0, TAU); CX.fill();
      CX.fillStyle = '#4a3a22'; CX.beginPath(); CX.arc(o.x - 3, o.y - 3, o.r * .7, 0, TAU); CX.fill();
    } else {
      for (let i = 0; i < 5; i++) {
        CX.fillStyle = i % 2 ? '#6e6448' : '#5d5439';
        CX.beginPath();
        CX.ellipse(o.x + Math.cos(i * 1.4) * o.r * .5, o.y + Math.sin(i * 1.4) * o.r * .4, o.r * .55, o.r * .4, i, 0, TAU);
        CX.fill();
      }
      CX.strokeStyle = 'rgba(0,0,0,.25)'; CX.stroke();
    }
  }
}
function drawBoss(e) {
  const b = e.boss;
  // aura
  CX.fillStyle = 'rgba(176,71,59,' + (.08 + .05 * Math.sin(performance.now() / 300)) + ')';
  CX.beginPath(); CX.arc(e.x, e.y, e.r + 26, 0, TAU); CX.fill();
  drawSoldier(CX, e.x, e.y, e.ang, { body: b.color, alt: '#151510', skin: '#c98d5f', head: 0, paint: 2, prot: .5, scale: e.r / 11 });
  // shoulder stars
  CX.fillStyle = '#c8a84b';
  CX.save(); CX.translate(e.x, e.y); CX.rotate(e.ang + Math.PI / 2);
  [-8, 8].forEach(sx => { CX.beginPath(); for (let i = 0; i < 5; i++) CX.lineTo(sx + Math.cos(i * TAU / 5 * 2) * 4, -2 + Math.sin(i * TAU / 5 * 2) * 4); CX.fill(); });
  CX.restore();
}
function drawPickup(k) {
  const bob = Math.sin(k.t * 4) * 2;
  CX.save(); CX.translate(k.x, k.y + bob);
  CX.fillStyle = 'rgba(0,0,0,.25)'; CX.beginPath(); CX.ellipse(0, 6, 9, 4, 0, 0, TAU); CX.fill();
  if (k.kind === 'hp') {
    CX.fillStyle = '#d9d0b4'; CX.fillRect(-7, -6, 14, 12);
    CX.fillStyle = '#b0473b'; CX.fillRect(-2, -4, 4, 8); CX.fillRect(-5, -1, 10, 3);
  } else if (k.kind === 'ammo') {
    CX.fillStyle = '#6e6448'; CX.fillRect(-8, -5, 16, 10);
    CX.fillStyle = '#4a4229'; CX.fillRect(-8, -5, 16, 3);
    CX.fillStyle = '#c8a84b'; CX.fillRect(-5, 0, 10, 2);
  } else {
    CX.fillStyle = '#7fb069'; CX.font = 'bold 11px Georgia'; CX.textAlign = 'center'; CX.fillText('$' + k.v, 0, 1);
  }
  CX.restore();
}
function drawHUD() {
  const p = R.run.p, g = p.wi === 1 ? p.w1 : p.w2;
  const x0 = G.cam.x, y0 = G.cam.y;
  CX.textAlign = 'left';
  // health
  const bw = 260;
  CX.fillStyle = 'rgba(10,8,5,.72)'; CX.fillRect(x0 + 18, y0 + VH - 78, bw + 16, 58);
  CX.fillStyle = '#2a2a20'; CX.fillRect(x0 + 26, y0 + VH - 68, bw, 14);
  CX.fillStyle = p.hp > 40 ? '#8faa52' : '#b0473b';
  CX.fillRect(x0 + 26, y0 + VH - 68, bw * clamp(p.hp / p.hpMax, 0, 1), 14);
  // stamina
  CX.fillStyle = '#2a2a20'; CX.fillRect(x0 + 26, y0 + VH - 50, bw, 7);
  CX.fillStyle = '#4a7080'; CX.fillRect(x0 + 26, y0 + VH - 50, bw * p.stamina / 100, 7);
  CX.fillStyle = '#e8dcc2'; CX.font = '11px Georgia';
  CX.fillText((S.name || 'Pvt. Somebody').toUpperCase() + '   HP', x0 + 26, y0 + VH - 72);
  CX.fillStyle = '#a3997e';
  const arm = armorById(S.armor), cl = CLOTHES[S.cloth];
  CX.fillText('ARMOR ' + Math.round(arm.prot * 100) + '% · ' + cl.n.toUpperCase(), x0 + 26, y0 + VH - 30);
  // weapon block
  CX.fillStyle = 'rgba(10,8,5,.72)'; CX.fillRect(x0 + VW - 300, y0 + VH - 78, 282, 58);
  CX.fillStyle = g === p.w1 ? '#c8a84b' : '#a3997e'; CX.font = '15px Georgia';
  CX.fillText('[' + (p.wi === 1 ? '1' : ' ']'), x0 + VW - 292, y0 + VH - 60);
  CX.fillStyle = '#e8dcc2'; CX.font = '16px Georgia';
  CX.fillText(g.w.n.length > 33 ? g.w.n.slice(0, 32) + '…' : g.w.n, x0 + VW - 258, y0 + VH - 59);
  CX.fillStyle = '#c8a84b'; CX.font = 'bold 22px Georgia';
  CX.fillText(g.mag + '/' + g.reserve, x0 + VW - 292, y0 + VH - 32);
