/* ---------------- input ---------------- */
addEventListener('keydown', e => {
  const k = e.key.toLowerCase();
  G.keys[k] = true;
  if (e.key === 'Escape') { if (G.scene === 'game') pause(true); else if (G.scene === 'paused') pause(false); }
  if (G.scene === 'game') {
    if (k === 'r') startReload();
    if (k === '1' || k === '2') switchW(+k);
    if (k === 'g') throwGrenade();
    if (k === ' ') e.preventDefault();
  }
  if (k.startsWith('arrow') || k === ' ') e.preventDefault();
});
addEventListener('keyup', e => G.keys[e.key.toLowerCase()] = false);
CV.addEventListener('mousemove', e => {
  const r = CV.getBoundingClientRect();
  G.mx = (e.clientX - r.left) * (CV.width / r.width);
  G.my = (e.clientY - r.top) * (CV.height / r.height);
});
CV.addEventListener('mousedown', () => { audio(); if (G.scene === 'game') { G.md = true; fireTick(true); } });
addEventListener('mouseup', () => G.md = false);
CV.addEventListener('contextmenu', e => e.preventDefault());
function pause(on) { if (!R || G.scene === 'over') return; G.scene = on ? 'paused' : 'game'; screen('scr-pause', on); if (!on) hideScreens(); }
function startReload() {
  const g = curGun();
  if (g.reload > 0 || g.mag === g.w.m || g.reserve <= 0) return;
  g.reload = g.w.rl; sReload();
}
function switchW(i) {
  const p = R.run.p; if (p.wi === i || !G['w' === 'x']) return;
  p.wi = i; tone(320, .05, .07, 'square');
}
function throwGrenade() {
  const p = R.run.p;
  if (p.grenades <= 0) { sDry(); return; }
  p.grenades--; sGren();
  const a = p.ang;
  R.run.lobs.push({ x: p.x + Math.cos(a) * 16, y: p.y + Math.sin(a) * 16, vx: Math.cos(a) * 280, vy: Math.sin(a) * 280, t: .85, kind: 'frag', dmg: 95 });
}

/* ---------------- shooting ---------------- */
function fireTick(click) {
  if (!R) return;
  const p = R.run.p, g = curGun(), w = g.w;
  if (g.reload > 0 || g.cool > 0) return;
  if (g.mag <= 0) { if (click) { sDry(); startReload(); } return; }
  if (w.md !== 'auto' && !click) return;
  g.cool = 60 / w.r; g.mag--;
  p.ang = Math.atan2(G.my + G.cam.y - p.y, G.mx + G.cam.x - p.x);
  sShot(w);
  G.shake = Math.min(10, G.shake + (w.c === 'SN' ? 5 : w.c === 'SG' ? 4 : 1.6));
  const n = w.pc || 1;
  for (let i = 0; i < n; i++) {
    const a = p.ang + rnd(-w.sp, w.sp) * (n > 1 ? .9 : 1);
    R.run.bullets.push({ x: p.x + Math.cos(p.ang) * 20, y: p.y + Math.sin(p.ang) * 20, vx: Math.cos(a) * 900, vy: Math.sin(a) * 900, dmg: w.d, from: 'p', r: w.c === 'SP' ? 4 : 2, range: w.rng, c: w.c });
  }
  for (let i = 0; i < 3; i++) R.run.parts.push({ x: p.x + Math.cos(p.ang) * 24, y: p.y + Math.sin(p.ang) * 24, vx: Math.cos(p.ang) * rnd(50, 180), vy: Math.sin(p.ang) * rnd(50, 180), life: .08, t: 0, kind: 'flash' });
}
function enemyFire(e, dmg) {
  const p = R.run.p;
  const a = ang(e.x, e.y, p.x, p.y) + rnd(-e.t.spread, e.t.spread);
  R.run.bullets.push({ x: e.x + Math.cos(a) * (e.r + 8), y: e.y + Math.sin(a) * (e.r + 8), vx: Math.cos(a) * 620, vy: Math.sin(a) * 620, dmg, from: 'e', r: 2.4, range: e.t.range, c: 'E' });
