  if (e.hp <= 0) killEnemy(e);
}
function blood(x, y) { return { x, y, vx: rnd(-90, 90), vy: rnd(-90, 90), life: rnd(.25, .55), t: 0, kind: 'blood' }; }
function killEnemy(e) {
