  R.run.enemies.forEach(en => {
    if (!en.dead && (side === 'p' || side === 'fx') && dist(en.x, en.y, x, y) < radius + en.r) {
      en.hp -= dmg * (1 - dist(en.x, en.y, x, y) / (radius + en.r));
      if (en.hp <= 0) killEnemy(en);
