}
function addCash(c, x, y) { S.req += c; R.run.cashRun += c; save(); if (x !== undefined) { floaty(x, y, '+$' + c); sCash(); } }
function floaty(x, y, txt) { R.run.parts.push({ x, y, vy: -40, vx: rnd(-10, 10), life: 1, t: 0, kind: 'txt', txt }); }
function die() {
  G.scene = 'over'; R.overT = .8;
  explode(R.run.p.x, R.run.p.y, 120, 0, 'fx');
  setTimeout(() => {
    S.bestRound = Math.max(S.bestRound, R.run.round);
    S.bestScore = Math.max(S.bestScore, R.run.score);
    save();
    document.getElementById('overStats').innerHTML =
      `SPC. ${esc(S.name || 'SOMEBODY')} bore east to ${R.run.round - 1} cleared rounds.<br>
       ${R.run.kills} kills this tour · score ${R.run.score} · requisition earned this tour $${R.run.cashRun}<br>
       <span style="color:#7fb069">Lifetime: round ${S.bestRound} · ${S.totalKills} kills · requisition bank $${S.req}</span>`;
    screen('scr-over', true);
