const $ = id => document.getElementById(id);

/* ---------------- screens & store ---------------- */
function screen(id, on) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('on'));
  if (on) $(id).classList.add('on');
}
let storeSel = null, storeTab = 'BR';
function renderTabs() {
  const tabs = [['BR', 'BATTLE'], ['AR', 'RIFLES'], ['SM', 'SMG'], ['SG', 'SHOTGUNS'], ['SN', 'SNIPER'], ['MG', 'LMG'], ['PI', 'PISTOLS'], ['SP', 'SPECIAL'], ['ARMOR', 'ARMOR'], ['CLOTH', 'CLOTHING']];
  const el = $('catTabs'); el.innerHTML = '';
  tabs.forEach(([k, lab]) => {
    const t = document.createElement('span');
    t.className = 'tab' + (storeTab === k ? ' on' : ''); t.textContent = lab;
    t.onclick = () => { storeTab = k; storeSel = null; renderTabs(); renderStore(); renderDetail(); };
    el.appendChild(t);
  });
}
function renderStore() {
  const L = $('wlist'); L.innerHTML = '';
  if (storeTab === 'ARMOR') {
    ARMORS.forEach((a, i) => {
      const owned = S.ownedArm.includes(i);
      const row = document.createElement('div');
      row.className = 'witem' + (storeSel && storeSel.kind === 'armor' && storeSel.i === i ? ' sel' : '') + (owned ? ' owned' : '');
