      L.appendChild(row);
    });
  } else if (storeTab === 'CLOTH') {
    CLOTHES.forEach((a, i) => {
      const owned = S.ownedCloth.includes(i), inUse = S.cloth === i;
      const row = document.createElement('div');
      row.className = 'witem' + (storeSel && storeSel.kind === 'cloth' && storeSel.i === i ? ' sel' : '') + (owned ? ' owned' : '');
      row.innerHTML = '<span class="n">' + a.n + (inUse ? ' ✔' : '') + '</span><span class="pr">' + (owned ? 'OWNED' : '$' + a.p) + '</span>';
      row.onclick = () => { storeSel = { kind: 'cloth', i }; renderStore(); renderDetail(); };
      L.appendChild(row);
    });
    BOOTS.forEach((a, i) => {
      const owned = S.ownedBoots.includes(i), inUse = S.boots === i;
      const row = document.createElement('div');
      row.className = 'witem' + (storeSel && storeSel.kind === 'boots' && storeSel.i === i ? ' sel' : '') + (owned ? ' owned' : '');
      row.innerHTML = '<span class="n">' + a.n + (inUse ? ' ✔' : '') + '</span><span class="pr">' + (owned ? 'OWNED' : '$' + a.p) + '</span>';
