}

/* ---------------- damage & economy ---------------- */
function hurtPlayer(d) {
  const p = R.run.p;
  if (p.iFrames > 0 || G.scene !== 'game') return;
  p.hp -= d * (1 - p.prot);
  p.iFrames = .25; p.hurtT = .45; G.shake = Math.min(14, G.shake + 4); sHurt();
  for (let i = 0; i < 5; i++) R.run.parts.push(blood(p.x, p.y));
