}
const esc = s => String(s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

/* ---------------- main update ---------------- */
function tick(now) {
  const dt = Math.min(.05, (now - last) / 1000); last = now;
  if (G.scene === 'game' && R) update(dt);
  render();
  requestAnimationFrame(tick);
}
let last = performance.now();
function update(dt) {
  const ru = R, p = ru.p;
  ru.time += dt;
  p.ang = Math.atan2(G.my + G.cam.y - p.y, G.mx + G.cam.x - p.x);
  const kx = (G.keys.d || G.keys.arrowright ? 1 : 0) - (G.keys.a || G.keys.arrowleft ? 1 : 0);
  const ky = (G.keys.s || G.keys.arrowdown ? 1 : 0) - (G.keys.w || G.keys.arrowup ? 1 : 0);
  const ml = Math.hypot(kx, ky) || 1;
  const wantSprint = G.keys.shift && (kx || ky) && p.stamina > 2;
  p.stamina = clamp(p.stamina + (wantSprint ? -32 : 20) * dt, 0, 100);
  const spd = 195 * p.spdMul * (wantSprint ? 1.45 : 1);
  p.x = clamp(p.x + kx / ml * spd * dt, 20, WW - 20); p.y = clamp(p.y + ky / ml * spd * dt, 20, WH - 20);
  for (const o of ru.obstacles) {
    const d = dist(p.x, p.y, o.x, o.y), mn = o.r + p.r;
    if (d < mn) { const nx = (p.x - o.x) / (d || 1), ny = (p.y - o.y) / (d || 1); p.x = o.x + nx * mn; p.y = o.y + ny * mn; }
  }
  p.iFrames = Math.max(0, p.iFrames - dt); p.hurtT = Math.max(0, p.hurtT - dt);
  for (const gg of [p.w1, p.w2]) {
    gg.cool = Math.max(0, gg.cool - dt);
    if (gg.reload > 0) {
      gg.reload -= dt;
      if (gg.reload <= 0) { const use = Math.min(gg.w.m - gg.mag, gg.reserve); gg.mag += use; gg.reserve -= use; gg.reload = 0; }
    }
  }
  if (G.md) fireTick(false);

  // spawning
  if (!ru.boss && ru.toSpawn > 0) {
    ru.spawnT -= dt;
    if (ru.spawnT <= 0 && ru.enemies.length < 30) {
      ru.spawnT = Math.max(.4, 1.5 - ru.round * .055);
      spawnAt(R.cfg.types[Math.floor(rnd(0, R.cfg.types.length))]);
      ru.toSpawn--;
    }
  }
  if (!ru.boss && ru.toSpawn === 0 && ru.enemies.length === 0) return roundClear();

  // taunt bots steal targets
  const tauntBots = ru.bots.filter(b => !b.dead && b.bot.trait === 'taunt');
  for (const e of ru.enemies) {
    if (e.dead) continue;
    e.targetBot = null;
    for (const b of tauntBots) if (dist(e.x, e.y, b.x, b.y) < 240) { e.targetBot = b; break; }
  }

  // squad robots
  for (const b of ru.bots) {
    if (b.dead) continue;
    // follow slot behind player
    const off = p.ang + Math.PI + (b.slot - 1) * .85;
    const fx = p.x + Math.cos(off) * 58, fy = p.y + Math.sin(off) * 58;
    // pick target
    let tgt = null, best = 1e9;
    for (const e of ru.enemies) {
      if (e.dead) continue;
      const d = dist(b.x, b.y, e.x, e.y);
      if (d < b.T.range && d < best) { best = d; tgt = e; }
    }
    const engage = !!tgt;
    let mx = fx - b.x, my = fy - b.y;
    const dm = Math.hypot(mx, my);
    const bspd = 170 + b.bot.tier * 8;
    if (dm > 14) { b.x += mx / dm * bspd * dt; b.y += my / dm * bspd * dt; }
    else if (tgt) { b.x += Math.cos(angTo(b.x, b.y, tgt.x, tgt.y)) * 12 * dt; b.y += Math.sin(angTo(b.x, b.y, tgt.x, tgt.y)) * 12 * dt; }
    if (tgt) b.ang = angTo(b.x, b.y, tgt.x, tgt.y); else if (dm > 14) b.ang = Math.atan2(my, mx);
    // firing
    b.cool -= dt;
    if (b.burstLeft > 0 && b.cool <= 0 && tgt) { botFire(b, tgt); b.burstLeft--; b.cool = .09; }
    else if (b.burstLeft === 0 && tgt && b.cool <= 0) {
      botFire(b, tgt);
      if (b.T.burst > 1) b.burstLeft = b.T.burst - 1;
      b.cool = 60 / b.T.rpm + b.T.gap;
    }
    // trait specials
    if (b.bot.trait === 'medic') {
      b.healT -= dt;
      if (b.healT <= 0 && dist(b.x, b.y, p.x, p.y) < 320 && p.hp < p.hpMax) {
        b.healT = b.T.healEvery; p.hp = Math.min(p.hpMax, p.hp + b.T.healAmt);
        floaty(p.x, p.y - 18, 'PATCHED +' + b.T.healAmt); sHeal();
        for (let i = 0; i < 6; i++) ru.parts.push({ x: p.x + rnd(-10, 10), y: p.y + rnd(-10, 10), vy: -30, vx: 0, life: .5, t: 0, kind: 'glint' });
      } else if (b.healT <= 0) b.healT = 2;
    }
    if (b.bot.trait === 'frag') {
      b.nadeT -= dt;
      if (b.nadeT <= 0 && tgt) {
        b.nadeT = b.T.nadeEvery; sGren();
        const a = angTo(b.x, b.y, tgt.x, tgt.y);
        ru.lobs.push({ x: b.x, y: b.y, vx: Math.cos(a) * 260, vy: Math.sin(a) * 260, t: Math.max(.2, dist(b.x, b.y, tgt.x, tgt.y) / 290), kind: 'frag', dmg: 40 + b.bot.tier * 22, side: 'p' });
      }
    }
    if (b.bot.trait === 'supply') {
      b.crateT -= dt;
      if (b.crateT <= 0) {
        b.crateT = b.T.crateEvery;
        ru.pickups.push({ x: b.x + rnd(-20, 20), y: b.y + rnd(-20, 20), kind: 'ammo', v: 0, t: 0 });
        floaty(b.x, b.y, 'CRATE'); tone(300, .1, .09, 'triangle');
      }
    }
    for (const o of ru.obstacles) {
      const d = dist(b.x, b.y, o.x, o.y), mn = o.r + 10;
      if (d < mn) { const nx = (b.x - o.x) / (d || 1), ny = (b.y - o.y) / (d || 1); b.x = o.x + nx * mn; b.y = o.y + ny * mn; }
    }
  }

  // enemies
  for (const e of ru.enemies) {
    if (e.dead) continue;
    const tgt = e.targetBot && !e.targetBot.dead ? e.targetBot : p;
    const a = angTo(e.x, e.y, tgt.x, tgt.y); e.ang = a;
    const d = dist(e.x, e.y, tgt.x, tgt.y);
    const boss = e.kind === 'boss';
    const range = boss ? e.t.range : e.t.range || 0;
    const stopAt = boss ? (e.boss.gun ? range * .78 : 34) : range > 0 ? range * .85 : 22;
    // jammer slow
    let slow = 1;
    for (const b of ru.bots) if (!b.dead && b.bot.trait === 'jammer' && dist(e.x, e.y, b.x, b.y) < 210) { slow = .45; break; }
    const wav = Math.sin(ru.time * (e.kind === 'sapper' ? 5 : 3) + e.strafe * 6);
    if (range === 0 || d < stopAt || e.kind === 'rusher' || e.kind === 'sapper') {
      const sp = e.spd * slow;
      e.x += (Math.cos(a) * sp + Math.cos(a + Math.PI / 2) * wav * 46) * dt;
      e.y += (Math.sin(a) * sp + Math.sin(a + Math.PI / 2) * wav * 46) * dt;
      if (e.kind === 'sapper' && d < e.r + (tgt.r || 12) + 8) { explode(e.x, e.y, 70, e.t.dmg, 'e'); killEnemy(e); continue; }
      if (e.kind === 'rusher') {
        e.meleeT -= dt;
        if (d < e.r + (tgt.r || 12) + 6 && e.meleeT <= 0) {
