    // bullets
    for (const b of R.run.bullets) {
      CX.strokeStyle = b.from === 'p' ? '#ffe9a8' : b.from === 'b' ? '#8ecae6' : '#ff8b6b';
      CX.lineWidth = b.r + (b.c === 'SN' ? 1.2 : 0);
      CX.beginPath(); CX.moveTo(b.x - b.vx * .016, b.y - b.vy * .016); CX.lineTo(b.x, b.y); CX.stroke();
    }
