  CX.fillStyle = '#a3997e'; CX.font = '12px Georgia';
  CX.fillText(bossOn ? 'KILL THE BOSS' : ('HOSTILES: ' + aliveLeft + (R.run.toSpawn ? ' + ' + R.run.toSpawn + ' inbound' : '')), VW / 2, 76);
  // req
  CX.textAlign = 'right'; CX.font = '14px Georgia'; CX.fillStyle = '#7fb069';
