let storeSel = null, storeTab = 'SQUAD', lastCrateResult = null;
.storeTabs;
const STORE_TABS = [['SQUAD', 'SQUAD ROBOTS'], ['CRATES', 'CRATE DEPÔT'], ['ARMOR', 'ARMOR'], ['CLOTH', 'CLOTHING'],
['BR', 'BATTLE'], ['AR', 'RIFLES'], ['SM', 'SMG'], ['SG', 'SHOTGUNS'], ['SN', 'SNIPER'], ['MG', 'LMG'], ['PI', 'PISTOLS'], ['SP', 'SPECIAL']];
function renderTabs() {
