function tierBadge(t) { return '<span style="color:' + TIER_COL[t - 1] + ';font-size:11px;letter-spacing:.1em">T' + t + ' ' + TIER_NAMES[t - 1] + '</span>'; }
function renderStore() {
  const L = $('wlist'); L.innerHTML = '';
  const addRow = (html, cls, onclick) => {
