      L.appendChild(hdr);
      ROBOTS.filter(r => r.tier === t).forEach(r => {
        const owned = S.ownedBots.includes(r.name);
        const equipped = S.squad.includes(r.name);
        addRow('<span class="n">' + r.name + (equipped ? ' ✔' : '') + '</span><span class="pr">' + (owned ? TIER_NAMES[t - 1].slice(0, 3) : 'CRATE ONLY') + '</span>',
