function equipSquad(slot) {
  if (!storeSel || !storeSel.name) return;
  if (!S.ownedBots.includes(storeSel.name)) return;
  const i = slot - 1;
  if (S.squad[i] === storeSel.name) return;
  const dup = S.squad.indexOf(storeSel.name);
