      '<div><span class="k">Price</span><br>$' + w.price + '</div></div>' +
      '<div class="wd">' + blurb + '</div>';
    $('b-buy').textContent = owned ? 'OWNED' : 'BUY $' + w.price;
    $('b-buy').disabled = owned ? true : S.req < w.price;
  }
}
/* crate roll: 1 gear item + 2 robots */
function openCrate() {
  const c = CRATES[storeSel.i];
  if (S.req < c.price) return;
  S.req -= c.price;
  S.cratesBought = S.cratesBought || [0, 0, 0];
  S.cratesBought[storeSel.i]++;
  const lines = [];
  // gear item
  const tierRoll = () => { const r = Math.random() * 100; let acc = 0; for (let i = 0; i < 5; i++) { acc += c.tierW[i]; if (r < acc) return i + 1; } return 1; };
  let gearKind = Math.random() < .55 ? 'weapon' : Math.random() < .45 ? 'armor' : 'cloth';
  let gearLine = '';
  if (gearKind === 'weapon') {
    const pool = WEAPONS.filter(w => w.tier === tierRoll());
    const pick = pool.length ? pool[Math.floor(rnd(0, pool.length))] : WEAPONS[Math.floor(rnd(0, WEAPONS.length))];
    if (!S.ownedW.includes(pick.n)) { S.ownedW.push(pick.n); gearLine = 'Item: ' + pick.n; }
    else { const back = Math.round(pick.price * .4); S.req += back; S.req -= 1; S.req++; gearLine = 'Extra frame scrapped (+$' + back + ')'; }
  } else if (gearKind === 'armor') {
    const t = tierRoll();
    const idx = ARMOR_TIER.map((v, i) => v === t ? i : -1).filter(i => i >= 0 && !S.ownedArm.includes(i));
    if (idx.length) { const pick = idx[Math.floor(rnd(0, idx.length))]; S.ownedArm.push(pick); gearLine = 'Item: ' + ARMORS[pick].n; }
    else { const back = Math.round(CRATES[storeSel.i].price * .3); S.req += back; S.crit = S.crit; gearLine = 'Armor depot fat (+$' + back + ')'; }
  } else {
    const isBoot = Math.random() < .35;
    const tiers = isBoot ? BOOT_TIER : CLOTH_TIER;
    const arr = isBoot ? BOOTS : CLOTHES;
    const t = tierRoll();
    const ownArr = isBoot ? S.ownedBoots : S.ownedCloth;
    const idx = tiers.map((v, i) => v >= t - 1 && v <= t ? i : -1).filter(i => i >= 0 && !ownArr.includes(i));
    if (idx.length) {
      const pick = idx[Math.floor(rnd(0, idx.length))];
      ownArr.push(pick);
      gearLine = 'Item: ' + arr[pick].n;
    } else { const back = Math.round(c.price * .25); S.req += back; gearLine = 'Clothing depot excess (+$' + back + ')'; }
  }
  lines.push(gearLine);
  // two robot rolls
  for (let k = 0; k < 2; k++) {
    const t = tierRoll() || 1;
    let tried = 0, bot = null;
    while (tried++ < 6 && !bot) {
      const pool = ROBOTS.filter(r => r.tier === Math.min(5, t + Math.floor(tried / 3)) );
      const unowned = pool.filter(r => !S.ownedBots.includes(r.name));
      if (unowned.length) bot = unowned[Math.floor(rnd(0, unowned.length))];
    }
    if (bot) { S.ownedBots.push(bot.name); lines.push('Robot: ' + bot.name + ' (T' + bot.tier + ' ' + TIER_NAMES[bot.tier - 1] + ' · ' + BOT_TRAIT_INFO[bot.trait].n + ')'); }
    else { const back = BOT_VAL(t); S.req += back; lines.push('Frame slot full → salvaged (+$' + back + ')'); }
  }
  lastCrateResult = { crate: c.n, lines };
  sLoot();
  save(); renderStore(); renderDetail(); refreshTop(); renderChar();
}
function buyOrEquip() {
  if (!storeSel) return;
  if (storeSel.kind === 'crate') return openCrate();
  if (storeSel.tier && !storeSel.kind) return; // robots come from crates only
  if (storeSel.kind === 'armor') {
    const a = ARMORS[storeSel.i];
    if (!S.ownedArm.includes(storeSel.i)) { if (S.req < a.p) return; S.req -= a.p; S.ownedArm.push(storeSel.i); }
    S.armor = storeSel.i;
  } else if (storeSel.kind === 'cloth' || storeSel.kind === 'boots') {
    const a = (storeSel.kind === 'cloth' ? CLOTHES : BOOTS)[storeSel.i];
    const own = storeSel.kind === 'cloth' ? S.ownedCloth : S.ownedBoots;
    if (!own.includes(storeSel.i)) { if (S.req < a.p) return; S.req -= a.p; own.push(storeSel.i); }
    S[storeSel.kind] = storeSel.i;
  } else if (storeSel.kind === 'weapon') {
    if (!S.ownedW.includes(storeSel.n)) { if (S.req < storeSel.price) return; S.req -= storeSel.price; S.ownedW.push(storeSel.n); }
  }
  save(); renderStore(); renderDetail(); refreshTop();
}
function equipWeapon(slot) {
  if (!storeSel || storeSel.kind !== 'weapon') return;
  if (!S.ownedW.includes(storeSel.n)) return;
  if (slot === 1) S.primary = storeSel.n; else S.sidearm = storeSel.n;
  save(); refreshTop(); renderDetail();
}
function refreshTop() {
  ['1', '2'].forEach(i => {
    $('tsReq' + i).textContent = '$' + S.req;
    $('tsBest' + i).textContent = S.bestRound ? 'Best round ' + S.bestRound + ' · ' + S.totalKills + ' kills · ' + S.ownedBots.length + ' robots' : 'No tours yet';
    $('tsWho' + i).textContent = 'SPC. ' + (S.name || 'SOMEBODY').toUpperCase();
  });
  $('slot1').textContent = S.primary || '—';
  $('slot2').textContent = S.sidearm || '—';
  $('slotA').textContent = ARMORS[S.armor].n;
  const names = S.squad.map(n => n || 'EMPTY');
  $('slotS').textContent = names.join(' · ') === 'EMPTY · EMPTY · EMPTY' ? '— all slots open —' : names.join(' · ') + ' (+' + buffSummary() + ')';
}
function buffSummary() {
  const b = computeBuffs();
  const out = [];
  if (b.dmg) out.push('DMG ' + Math.round(b.dmg * 100) + '%');
  if (b.spd) out.push('SPD ' + Math.round(b.spd * 100) + '%');
  if (b.hp) out.push('HP +' + Math.round(b.hp * 100));
  if (b.prot) out.push('ARM +' + Math.round(b.prot * 100) + '%');
  if (b.reload) out.push('RLD ' + Math.round(b.reload * 100) + '%');
  return out.join(', ');
}

/* ---------------- barracks ---------------- */
function pills(rowEl, list, cur, cb) {
  const el = $(rowEl); el.innerHTML = '';
  list.forEach((label, i) => {
    const p = document.createElement('span');
    p.className = 'pill' + (cur === i ? ' on' : '');
    p.textContent = label; p.onclick = () => cb(i);
    el.appendChild(p);
  });
}
function renderChar() {
  $('inName').value = S.name;
  const sk = $('swSkin'); sk.innerHTML = '';
  SKINS.forEach((c, i) => {
    const d = document.createElement('div'); d.className = 'sw' + (S.skin === i ? ' on' : ''); d.style.background = c;
    d.onclick = () => { S.skin = i; save(); renderChar(); }; sk.appendChild(d);
  });
  pills('rowHead', HEADWEAR, S.head, i => { S.head = i; save(); renderChar(); });
  pills('rowPaint', PAINT, S.paint, i => { S.paint = i; save(); renderChar(); });
  pills('rowCloth', CLOTHES.map((c, i) => c.n + (S.ownedCloth.includes(i) ? ' ✔' : ' $' + c.p)), S.cloth, i => {
    if (!S.ownedCloth.includes(i)) return charNote('Not issued — buy in the store ($' + CLOTHES[i].p + ').');
    S.cloth = i; save(); renderChar(); charNote('');
  });
  pills('rowBoots', BOOTS.map((b, i) => b.n + (S.ownedBoots.includes(i) ? ' ✔' : ' $' + b.p)), S.boots, i => {
    if (!S.ownedBoots.includes(i)) return charNote('Not issued — buy in the store ($' + BOOTS[i].p + ').');
    S.boots = i; save(); renderChar(); charNote('');
  });
  pills('rowArmor', ARMORS.map((a, i) => a.n + (S.ownedArm.includes(i) ? ' ✔' : ' $' + a.p)), S.armor, i => {
    if (!S.ownedArm.includes(i)) return charNote('Not issued — buy in the store ($' + ARMORS[i].p + ').');
    S.armor = i; save(); renderChar(); charNote('');
  });
  // squad strip
  const qs = $('charSquad');
  const sq = S.squad.map((n, i) => {
    const r = n && botByName(n);
    return r ? '<b style="color:' + TIER_COL[r.tier - 1] + '">' + r.name + '</b> (+' + Math.round(r.buffVal * 100) + '% ' + BUFF_LABEL[r.buff] + ')'
             : '<span style="opacity:.5">SLOT ' + (i + 1) + ': open</span>';
  });
  qs.innerHTML = 'SQUAD — ' + sq.join(' &nbsp;·&nbsp; ') + ' &nbsp; ' + (buffSummary() ? '<span style="color:#7fb069">BUFFS: ' + buffSummary() + '</span>' : '') +
    '<br>G.I. robots are recruited from the CRATE DEPÔT tab in the store (5 tiers · 10 frames each).';
  drawCharacter(); refreshTop();
}
function charNote(t) { $('charDetail').textContent = t; }
const chCx = $('charCanvas').getContext('2d');
function drawCharacter() {
  chCx.fillStyle = '#100e0a'; chCx.fillRect(0, 0, 240, 280);
  drawSoldier(chCx, 118, 128, 0, Object.assign(armorClothAll(), { scale: 3.4 }));
  // draw squad bots mini around
  S.squad.slice(0, 3).forEach((n, i) => {
    const r = n && botByName(n);
    if (r) drawRobot(chCx, 40 + i * 78, 218, 0, r, 1);
  });
  chCx.fillStyle = '#a3997e'; chCx.font = '11px Georgia'; chCx.textAlign = 'center';
  const cl = CLOTHES[S.cloth], arm = armorById(S.armor);
  chCx.fillText(cl.n + ' · ' + arm.n, 120, 252);
  chCx.fillText('BARRACKS PREVIEW', 120, 270);
}

/* ---------------- wiring ---------------- */
function wire() {
  $('tagline').textContent = WEAPONS.length + ' period weapons · 5 robot tiers · boss every 10th round';
  $('b-char').onclick = () => { audio(); G.scene = 'char'; screen('scr-char'); renderChar(); };
  $('b-armTitle').onclick = () => { audio(); openStore(); };
  $('b-back1').onclick = () => { G.scene = 'title'; screen('scr-title'); };
  $('b-toArmory').onclick = () => openStore();
  $('b-back2').onclick = () => { G.scene = 'char'; screen('scr-char'); renderChar(); };
  $('b-deploy').onclick = () => { audio(); deploy(); };
  $('b-set1').onclick = () => { if (storeSel && storeSel.tier && !storeSel.kind) equipSquad(1); else equipWeapon(1); };
  $('b-set2').onclick = () => { if (storeSel && storeSel.tier && !storeSel.kind) equipSquad(2); else equipWeapon(2); };
  $('b-set3').onclick = () => equipSquad(3);
  $('b-buy').onclick = buyOrEquip;
  $('b-next').onclick = () => nextRound();
  $('b-openArm').onclick = () => openStore();
  $('b-resume').onclick = () => pause(false);
  $('b-abort').onclick = () => { G.scene = 'title'; screen('scr-title'); };
  $('b-retry').onclick = () => deploy();
  $('b-armOver').onclick = () => openStore();
  $('b-menu').onclick = () => { G.scene = 'title'; screen('scr-title'); };
  $('inName').addEventListener('input', e => { S.name = e.target.value; save(); refreshTop(); });
  $('inName').addEventListener('keydown', e => e.stopPropagation());
}
function openStore() {
  G.scene = 'armory';
  screen('scr-arm');
  refreshTop(); renderTabs(); renderStore(); renderDetail();
}
/* go */
paintGround();
wire();
refreshTop();
renderChar();
requestAnimationFrame(tick);

