function wire() {
  $('tagline').textContent = WEAPONS.length + ' period weapons · 5 troop tiers · 4 areas · boss every 10th round';
  $('b-char').onclick = () => { audio(); G.scene = 'char'; screen('scr-char'); renderChar(); };
