import { chromium } from 'playwright';
import path from 'path';
const shots = process.argv[2] || '/tmp/opencode';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
const url = 'file://' + path.resolve('index.html');
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto(url);
await page.waitForTimeout(800);
const jpg = n => path.join(shots, n + '.jpg');
const grab = async (n) => { await page.screenshot({ path: jpg(n), quality: 55, type: 'jpeg' }); };

await grab('shot1-title');

await page.click('#b-char'); await page.waitForTimeout(400);
await grab('shot2-barracks');

// name + go to store, open a crate
await page.fill('#inName', 'SGT. BLOODWORTH');
await page.click('#b-toArmory'); await page.waitForTimeout(400);
await grab('shot3-store世界各地'.replace(/[^a-z3-]/g, '') || 'shot3-store');

// buy weapons: select M16 tab then buy something cheap & equip
await page.click('text=PISTOLS'); await page.waitForTimeout(200);
await grab('shot4-store-pistols');

// squad tab
await page.click('text=SQUAD — TROOPS'); await page.waitForTimeout(200);
await grab('shot5-store-squad');

// crates: buy one (default req 260 < 380, buy FIELD TRANSFER PAPERS at 160)
await page.click('text=REINFORCEMENT OFFICE'); await page.waitForTimeout(200);
await page.click('#wlist .witem'); await page.waitForTimeout(200);
await page.click('#b-buy'); await page.waitForTimeout(400);
await grab('shot6-crate-result');

// buy an armor + equip
await page.click('text=ARMOR').catch(() => {});
await page.waitForTimeout(300);
const armorTabs = await page.$$('#catTabs .tab');
// find armor by text content
for (const t of armorTabs) { if ((await t.textContent()).trim() === 'ARMOR') { await t.click(); break; } }
await page.waitForTimeout(200);
await page.click('#wlist .witem'); await page.waitForTimeout(150);
await page.click('#b-buy').catch(() => {});
await grab('shot7-armor-bought');

// equipment check: squad tab, equip if any owned
for (const t of await page.$$('#catTabs .tab')) { if ((await t.textContent()).trim().includes('SQUAD')) { await t.click(); break; } }
await page.waitForTimeout(200);
// click each witem, if an EQUIP button enabled (owned), set squad slot 1..3
const items = await page.$$('#wlist .witem');
let eq = 0;
for (const it of items) {
  await it.click(); await page.waitForTimeout(60);
  const disabled = await page.$eval('#b-set1', b => b.style.display === 'none' || b.disabled);
  if (!disabled && eq < 3) {
    const btn = ['#b-set1', '#b-set2', '#b-set3'][eq];
    const dis = await page.$eval(btn, b => b.style.display === 'none' || b.disabled);
    if (!dis) { await page.click(btn); eq++; }
  }
}
await grab('shot8-squad-equipped');

// deploy!
await page.click('#b-deploy'); await page.waitForTimeout(2500);
await grab('shot9-game-village');
await page.mouse.move(640, 300); await page.mouse.down({ button: 'left' });
await page.waitForTimeout(1600); await page.mouse.up();
await page.keyboard.down('d'); await page.waitForTimeout(900); await page.keyboard.up('d');
await grab('shot10-game-play');

// die fast? then check next round biome by winning; instead jump: evaluate nextRound after clearing — force roundClear for test
await page.evaluate(() => { if (window.R) { R.run.enemies.forEach(e => e.dead = true); R.run.toSpawn = 0; } });
await page.waitForTimeout(600);
await grab('shot11-inter');
await page.click('#b-next'); await page.waitForTimeout(2600);
await grab('shot12-game-round2');

console.log(JSON.stringify({ errors: errors.slice(0, 8), shot: jpg('shot12-game-round2') }));
await browser.close();

