import { chromium } from 'playwright-core';
import path from 'path';
const out = process.argv[2] || '/tmp/opencode';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('file://' + path.resolve('index.html'));
await page.waitForTimeout(700);
const grab = n => page.screenshot({ path: path.join(out, n + '.jpg'), quality: 55, type: 'jpeg' });

// 1. title — forest + Huey backdrop
await grab('shot1-title');

// 2. barracks — translucent, forest behind
await page.click('#b-char');
await page.waitForTimeout(400);
await page.fill('#inName', 'SGT. BLOODWORTH');
await grab('shot2-barracks');

// 3. loadout screen
await page.click('#b-toLoadout');
await page.waitForTimeout(400);
await grab('shot3-loadout');

// 4. S-4 store — buy a cheap pistol
await page.click('#b-back1 || css=body'); // placeholder never used

import { chromium } from 'playwright-core';
import path from 'path';
const out = process.argv[2] || '/tmp/opencode';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('file://' + path.resolve('index.html'));
await page.waitForTimeout(700);
const grab = n => page.screenshot({ path: path.join(out, n + '.jpg'), quality: 55, type: 'jpeg' });
const tabClick = async (sel, i) => { await page.click(`${sel} .tab >> nth=${i}`); await page.waitForTimeout(250); };

// 1. title — forest + Huey backdrop
await grab('shot1-title');

// 2. barracks — translucent panels over forest
await page.click('#b-char');
await page.waitForTimeout(400);
await page.fill('#inName', 'SGT. BLOODWORTH');
await grab('shot2-barracks');

// 3. loadout screen (owned weapons)
await page.click('#b-toLoadout');
await page.waitForTimeout(400);
await grab('shot3-loadout');
await page.click('#lo-list .witem >> nth=0');
await page.waitForTimeout(250);
await grab('shot3b-loadout-sel');

// 4. S-4 store — buy a cheap pistol (PISTOLS tab = index 6)
await page.click('#st-back');            // back to title
await page.click('#b-store');
await page.waitForTimeout(400);
await grab('shot4-store');
await tabClick('#st-tabs', 6);
await page.click('#st-list .witem >> nth=0');
await page.waitForTimeout(250);
await page.click('#st-buy');             // M1911 already owned → command; buy first unowned
// make sure req is enough: if disabled, skip
const buyDisabled = await page.$eval('#st-buy', b => b.disabled);
if (!buyDisabled) await page.click('#st-buy');
await page.waitForTimeout(300);
await page.click('#st-list .witem >> nth=4'); // pick a mid pistol; buy if enabled
await page.waitForTimeout(250);
await page.click('#st-buy');
await grab('shot4b-store-pistols');

// 5. squad screen — process a package (CRATES tab = index 1)
await page.click('#sq-tmp').catch(() => {}); // never exists; noop
await page.click('#st-back');
await page.click('#b-squad');
await page.waitForTimeout(400);
await tabClick('#sq-tabs', 1);
await page.click('#sq-list .witem >> nth=0');
await page.waitForTimeout(250);
await page.click('#sq-buy');             // FIELD TRANSFER PAPERS $160, start with $80 → may need funds
const sqBuyDisabled = await page.$eval('#sq-buy', b => b.disabled);
if (!sqBuyDisabled) await page.click('#sq-buy');
await page.waitForTimeout(300);
// grant funds if cheap crate still unaffordable (start cash 80, maybe spent)
await page.evaluate(() => { if (S && S.req < 300) { S.req += 400; save(); refreshTop(); } });
await tabClick('#sq-tabs', 0);
await grab('shot5-squad-roster');
await tabClick('#sq-tabs', 1);
await page.click('#sq-list .witem >> nth=0');
await page.waitForTimeout(200);
await page.click('#sq-buy');
await page.waitForTimeout(400);
await grab('shot5b-crate-result');

// 5c. assign any owned troops to slots
await tabClick('#sq-tabs', 0);
const items = await page.$$('#sq-list .witem');
let eq = 0;
for (const it of items) {
  await it.click(); await page.waitForTimeout(40);
  if (eq >= 3) break;
  const disabled = await page.$eval('#sq-set1', b => b.disabled);
  if (!disabled) { await page.click(`#sq-set${eq + 1}`); eq++; }
}
await grab('shot5c-squad-equipped');

// 6. deploy — village round
await page.click('#sq-deploy');
await page.waitForTimeout(2200);
await grab('shot6-village');

// 7. combat
await page.mouse.move(640, 320);
await page.mouse.down();
await page.waitForTimeout(1400);
await page.keyboard.down('d'); await page.waitForTimeout(700); await page.keyboard.up('d');
await page.mouse.up();
await grab('shot7-combat');

// 8. force clear → inter screen
await page.evaluate(() => { if (typeof R !== 'undefined' && R) { R.run.enemies.forEach(e => e.dead = true); R.run.toSpawn = 0; } });
await page.waitForTimeout(800);
const interOn = await page.$eval('#scr-inter', s => s.classList.contains('on'));
await grab('shot8-inter');
if (interOn) {
  await page.click('#b-inter-store');
  await page.waitForTimeout(300);
  await grab('shot8b-store-from-inter');
  await page.click('#st-back');           // store back → title
  // resume run: deploy continues from round state? title resets → just grab title again
  await grab('shot8c-title2');
}

// 9. full round 2 — paddies: restart a run, cheat to round 2
await page.evaluate(() => { localStorage.setItem('nam68_debug', '1'); if (R) { R.run.round = 2; R.run.lastCleared = 1; R = R; } });
await page.click('#b-load');
await page.waitForTimeout(250);
await page.click('#lo-deploy');
await page.waitForTimeout(500);
await page.evaluate(() => { if (R) { R.run.round = 2; R.run.lastCleared = 1; beginRound(); } });
await page.waitForTimeout(1600);
await grab('shot9-paddies');

console.log(JSON.stringify({ errors: errors.slice(0, 10), shots: out }));
await browser.close();

