Fix loop: for i in range of items.length, click `#sq-list .witem >> nth=i`, then evaluate enabled. Let me rewrite that block:

```
const n = await page.$$eval('#sq-list .witem', a => a.length);
for (let i = 0; i < n; i++) {
  if (eq >= 3) break;
  await page.click(`#sq-list .witem >> nth=${i}`); await page.waitForTimeout(40);
  if (!(await page.$eval('#sq-set1', b => b.disabled))) { await page.click(`#sq-set${eq + 1}`); eq++; }
}

